.site-header { border-bottom: 1px solid var(--line); }
.nav { min-height: 88px; display: flex; align-items: center; justify-content: space-between; gap: var(--space-8); }
.brand { display: inline-flex; align-items: center; gap: var(--space-3); font: 600 var(--text-xl)/1.2 var(--serif); letter-spacing: -.04em; }
.brand svg { color: var(--accent); }
.nav-links, .nav-actions { display: flex; align-items: center; gap: var(--space-8); font-size: var(--text-sm); }
