.button:hover { background: var(--accent-soft); border-color: var(--accent); }
.button:active { background: var(--line); }
.button-primary { background: var(--accent); border-color: var(--accent); color: var(--surface); }
.button-primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
.button-primary:active { background: var(--ink); }
.nav-actions .button { min-height: 44px; padding-inline: var(--space-4); }
.hero { padding-block: var(--space-16) var(--space-12); display: grid; grid-template-columns: 1.25fr 1fr; gap: var(--space-16); align-items: end; }
.eyebrow { display: flex; align-items: center; gap: var(--space-3); font-size: var(--text-xs); font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--accent); margin-bottom: var(--space-6); }
.eyebrow::before { content: ''; width: 24px; height: 1px; background: currentColor; }
h1 { font: 400 var(--text-display)/1.07 var(--serif); letter-spacing: -.055em; text-wrap: balance; }
h1 em { color: var(--accent); font-weight: 400; }
.hero-copy { padding-bottom: var(--space-2); max-width: 37ch; justify-self: end; }
.hero-copy p { font-size: var(--text-lg); color: var(--muted); line-height: 1.7; }
.hero-note { display: block; margin-top: var(--space-4); font-size: var(--text-sm); color: var(--ink); }
#pricing, #features, #faq { scroll-margin-top: var(--space-8); }
.pricing-tools { display: flex; justify-content: space-between; align-items: center; gap: var(--space-6); margin-bottom: var(--space-6); }
.pricing-tools h2 { font-size: var(--text-sm); font-weight: 500; color: var(--muted); }
.billing { display: flex; align-items: center; gap: var(--space-4); }
.billing-toggle { display: flex; padding: var(--space-1); border: 1px solid var(--control-border); border-radius: var(--radius); }
.billing-toggle button { min-height: 44px; padding: var(--space-2) var(--space-4); border: 0; border-radius: 4px; color: var(--muted); background: transparent; font-size: var(--text-sm); }
.billing-toggle button:hover { color: var(--ink); background: var(--accent-soft); }
.billing-toggle button[aria-pressed=\"true\"] { background: var(--accent); color: var(--surface); }
.saving { font-size: var(--text-xs); font-weight: 600; color: var(--accent); }
.plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-4); }
.plan { display: flex; flex-direction: column; position: relative; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: var(--space-8); }
.plan.popular { background: var(--accent-soft); border-color: var(--accent); }
