.description { font-size: var(--text-sm); color: var(--muted); margin-top: var(--space-2); min-height: 42px; }
.price { display: flex; align-items: baseline; gap: var(--space-2); margin-top: var(--space-6); white-space: nowrap; }
.price-value { font-size: 3rem; line-height: 1.15; letter-spacing: -.06em; font-weight: 500; font-variant-numeric: tabular-nums; }
.price-unit { font-size: var(--text-sm); color: var(--muted); }
.billing-note { color: var(--muted); font-size: var(--text-xs); margin-top: var(--space-2); min-height: 36px; }
.plan .button { width: 100%; margin-top: var(--space-4); justify-content: space-between; }
.plan .button svg { width: 16px; height: 16px; }
.plan-features { margin-top: var(--space-6); padding-top: var(--space-6); border-top: 1px solid var(--line); }
.feature-label { font-size: var(--text-xs); font-weight: 600; margin-bottom: var(--space-4); }
.plan ul { list-style: none; padding: 0; margin: 0; display: grid; gap: var(--space-3); }
.plan li { display: flex; align-items: baseline; gap: var(--space-3); font-size: var(--text-sm); }
.plan li::before { content: ''; display: block; flex: 0 0 12px; width: 12px; height: 7px; border-left: 1.5px solid var(--accent); border-bottom: 1.5px solid var(--accent); transform: translateY(-2px) rotate(-45deg); }
.plan li.unavailable { color: var(--muted); }
.plan li.unavailable::before { height: 1px; border-left: 0; border-bottom-color: var(--control-border); transform: translateY(-4px); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
.pricing-footnote { text-align: center; color: var(--muted); font-size: var(--text-xs); margin-top: var(--space-6); }
.features { margin-top: var(--space-24); padding-block: var(--space-12); border-block: 1px solid var(--line); display: grid; grid-template-columns: 1.2fr repeat(3, 1fr); gap: var(--space-8); }
.section-title { font: 400 var(--text-heading)/1.15 var(--serif); letter-spacing: -.04em; text-wrap: balance; }
.features .section-title { font-size: 2rem; }
.feature-icon { width: 24px; height: 24px; color: var(--accent); margin-bottom: var(--space-4); }
.feature h3 { font-size: var(--text-base); font-weight: 600; margin-bottom: var(--space-2); }
.feature p { font-size: var(--text-sm); line-height: 1.65; color: var(--muted); max-width: 27ch; }
.faq { display: grid; grid-template-columns: 1fr 1.6fr; gap: var(--space-16); padding-block: var(--space-24); }
.faq-intro p { color: var(--muted); margin-top: var(--space-4); font-size: var(--text-sm); }
.faq-list { border-top: 1px solid var(--line); }
details { border-bottom: 1px solid var(--line); }
summary { list-style: none; display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); padding-block: var(--space-6); cursor: pointer; font-size: var(--text-base); font-weight: 500; }
summary::-webkit-details-marker { display: none; }
summary::after { content: '+'; color: var(--accent); font-size: var(--text-xl); font-weight: 400; line-height: 1; }
details[open] summary::after { content: '−'; }
summary:hover { color: var(--accent); }
details p { color: var(--muted); font-size: var(--text-sm); line-height: 1.7; padding-bottom: var(--space-6); max-width: 60ch; }
.site-footer { border-top: 1px solid var(--line); }
.footer-inner { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); padding-block: var(--space-8); }
.footer-brand { font-size: 1.25rem; }
.footer-inner p { color: var(--muted); font-size: var(--text-xs); }
@media (min-width: 1440px) { .hero { padding-top: var(--space-24); } }
@media (max-width: 1000px) {
  .container { width: calc(100% - 64px); }
  .nav, .nav-links, .nav-actions { gap: var(--space-6); }
  .hero { gap: var(--space-8); }
  .plan { padding: var(--space-6); }
  .plan-heading { min-height: 64px; align-content: start; }
  .features { grid-template-columns: repeat(3, 1fr); }
