  .features > .section-title br { display: none; }
  .faq { gap: var(--space-8); }
}
@media (max-width: 760px) {
  .container { width: calc(100% - 40px); }
  .nav { min-height: 80px; flex-wrap: wrap; gap: 0; padding-top: var(--space-4); }
  .brand { font-size: 1.375rem; }
  .nav-actions { gap: var(--space-4); }
  .nav-actions .nav-link { display: none; }
  .nav-links { order: 3; width: 100%; justify-content: center; gap: var(--space-8); margin-top: var(--space-2); }
  .hero { grid-template-columns: 1fr; gap: var(--space-6); padding-block: var(--space-12); }
  .eyebrow { margin-bottom: var(--space-4); }
  .hero-copy { justify-self: start; max-width: 44ch; }
  .hero-copy p { font-size: var(--text-base); }
  .pricing-tools { align-items: start; flex-direction: column; gap: var(--space-4); }
  .billing { width: 100%; justify-content: space-between; }
  .plans { grid-template-columns: 1fr; gap: var(--space-6); }
  .plan { padding: var(--space-8); }
  .plan-heading { min-height: 0; }
  .description { min-height: 0; }
  .billing-note { min-height: 0; }
  .features { margin-top: var(--space-16); padding-block: var(--space-8); grid-template-columns: 1fr; gap: var(--space-8); }
  .feature { display: grid; grid-template-columns: 24px 1fr; column-gap: var(--space-4); }
  .feature-icon { grid-row: span 2; margin-bottom: 0; }
  .feature p { max-width: 40ch; }
  .features > .section-title br { display: initial; }
  .faq { grid-template-columns: 1fr; gap: var(--space-8); padding-block: var(--space-16); }
  .footer-inner { align-items: start; flex-direction: column; gap: var(--space-4); }
